const source = $json.body ?? $json;
const required = ['lead_id', 'idempotency_key', 'message', 'lead_score', 'lead_category'];
for (const field of required) {
  if (source[field] === undefined || source[field] === null || source[field] === '') {
    throw new Error('Missing required field: ' + field);
  }
}
if (!Number.isInteger(source.lead_score) || source.lead_score < 0 || source.lead_score > 100) {
  throw new Error('Invalid lead_score');
}
if (!['HOT', 'WARM', 'COLD'].includes(source.lead_category)) {
  throw new Error('Invalid lead_category');
}
const allowed = ['lead_id','idempotency_key','name','email','phone','message','property_type','location','bedrooms','budget','intent','timeline','lead_score','lead_category','human_agent','missing_fields','ambiguous_fields','ai_prompt_version'];
const clean = {};
for (const key of allowed) clean[key] = source[key] ?? null;
clean.message = String(clean.message).trim().slice(0, 5000);
clean.idempotency_key = String(clean.idempotency_key).trim().slice(0, 128);
return [{ json: clean }];

const state = $getWorkflowStaticData('global');
state.processedKeys ??= {};
const key = $json.idempotency_key;
return [{ json: { ...$json, duplicate: Boolean(state.processedKeys[key]) } }];

const item = $json;
const route = item.human_agent ? 'HUMAN_AGENT' : item.lead_category;
return [{ json: { ...item, route } }];

const state = $getWorkflowStaticData('global');
state.processedKeys ??= {};
state.processedKeys[$json.idempotency_key] = new Date().toISOString();
const keys = Object.keys(state.processedKeys);
if (keys.length > 5000) {
  for (const key of keys.slice(0, keys.length - 5000)) delete state.processedKeys[key];
}
return [{ json: $json }];
